// @domain: principles
//! #4766 — the spine log as tool calls: read only its end, join each call's start and end.
//! No crate dependencies beyond serde_json, so athena-gen's own tests compile it directly.
//! Generated by athena-gen from its template — DO NOT EDIT; change the generator.

use serde_json::Value;
use std::io::{Read, Seek, SeekFrom};

/// How much of the log's end one read takes. 4 MB holds about the last hour of calls.
#[allow(dead_code)]
pub const TAIL_BYTES: u64 = 4 * 1024 * 1024;

/// The log's last `max` bytes as text, without the partial first line. A missing or
/// unreadable log is an error (unmeasured), never an empty list that reads as "no work".
pub fn tail(path: &str, max: u64) -> Result<String, String> {
    let mut f = std::fs::File::open(path).map_err(|e| format!("spine log {path} unreadable: {e}"))?;
    let size = f.metadata().map_err(|e| format!("spine log {path}: {e}"))?.len();
    let start = size.saturating_sub(max);
    f.seek(SeekFrom::Start(start)).map_err(|e| format!("spine log {path}: {e}"))?;
    let mut buf = Vec::with_capacity((size - start) as usize);
    f.take(max).read_to_end(&mut buf).map_err(|e| format!("spine log {path}: {e}"))?;
    let text = String::from_utf8_lossy(&buf).into_owned();
    if start == 0 {
        return Ok(text);
    }
    Ok(text.split_once('\n').map(|(_, rest)| rest.to_string()).unwrap_or_default())
}

/// One tool call, joined from its start and end.
#[derive(Debug, Clone, PartialEq)]
pub struct Call {
    pub id: String,
    pub what: String,
    pub role: String,
    pub tool: String,
    pub ts: String,
    pub session: String,
    pub card: String,
    /// done, failed, running or stopped; "reply" for a reply (#4991)
    pub phase: String,
}

fn s(v: &Value, k: &str) -> String {
    match v.get(k) {
        Some(Value::String(x)) => x.clone(),
        Some(Value::Number(n)) => n.to_string(),
        _ => String::new(),
    }
}

/// The calls in `text`, newest first. `agent.action` lines make call rows; #4991:
/// `reply.emitted` lines make reply rows (phase "reply"), so a reply shows without
/// reading as work.
/// #4991 — a call logged with no call_id (Abby's runtime writes call_id "") is still a
/// call: its start gets an id from role, session and time, and an id-less end closes the
/// oldest open id-less start of the same role, session and tool (that runtime runs one
/// call at a time). The old Clearing showed these; the #4766 reader dropped them.
pub fn calls(text: &str) -> Vec<Call> {
    let mut started: Vec<Call> = Vec::new();
    let mut ended: std::collections::HashMap<String, String> = std::collections::HashMap::new();
    let mut open_idless: std::collections::HashMap<(String, String, String), std::collections::VecDeque<String>> = std::collections::HashMap::new();
    let mut turn_ends: Vec<(String, String, String)> = Vec::new(); // role, session, ts
    let mut seq = 0u64;
    for line in text.lines() {
        let Ok(v) = serde_json::from_str::<Value>(line) else { continue };
        match s(&v, "event").as_str() {
            "agent.action" => {
                let (given, tool) = (s(&v, "call_id"), s(&v, "tool"));
                if tool.is_empty() {
                    continue;
                }
                let (role, session, ts) = (s(&v, "role"), s(&v, "session_id"), s(&v, "timestamp"));
                let key = (role.clone(), session.clone(), tool.clone());
                if s(&v, "phase") == "ended" {
                    let id = if given.is_empty() {
                        match open_idless.get_mut(&key).and_then(|q| q.pop_front()) { Some(id) => id, None => continue }
                    } else { given };
                    let outcome = s(&v, "outcome");
                    ended.insert(id, if outcome.is_empty() { "ok".into() } else { outcome });
                } else {
                    let id = if given.is_empty() {
                        seq += 1;
                        let id = format!("{role}-{session}-{ts}-{seq}");
                        open_idless.entry(key).or_default().push_back(id.clone());
                        id
                    } else { given };
                    let digest = s(&v, "digest");
                    started.push(Call {
                        what: if digest.is_empty() { tool.clone() } else { digest },
                        id, tool, role, ts, session,
                        card: s(&v, "card_id"),
                        phase: String::new(),
                    });
                }
            }
            "reply.emitted" => {
                let (role, session, ts) = (s(&v, "role"), s(&v, "session"), s(&v, "timestamp"));
                if role.is_empty() {
                    continue;
                }
                let words = s(&v, "words");
                started.push(Call {
                    id: format!("reply-{role}-{ts}"),
                    what: if words.is_empty() { "replied".into() } else { format!("replied ({words} words)") },
                    tool: "reply".into(), role, ts, session, card: String::new(),
                    phase: "reply".into(),
                });
            }
            "agent.turn.ended" => {
                let (role, session) = (s(&v, "role"), s(&v, "session_id"));
                if !session.is_empty() {
                    // an id-less call still open when its turn ends never closes a later turn's call
                    open_idless.retain(|(r, sess, _), _| !(*r == role && *sess == session));
                    turn_ends.push((role, session, s(&v, "timestamp")));
                }
            }
            _ => {}
        }
    }
    for c in started.iter_mut().filter(|c| c.phase != "reply") {
        c.phase = match ended.get(&c.id) {
            Some(o) if o == "error" => "failed".into(),
            Some(_) => "done".into(),
            None if turn_ends.iter().any(|(r, sess, ts)| *r == c.role && *sess == c.session && *ts >= c.ts) => "stopped".into(),
            None => "running".into(),
        };
    }
    started.reverse();
    started
}

